// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: amount (uint256) and caller address
    // General rule tested: reference C accepts fallback only when value == 10 ether; for any other value it reverts.
    // We assert that for EVERY fuzzed input the reference's behavior (success vs revert) is: succeed iff value == 10 ether.
    // The one-statement mutant changing 10 ether to 5 ether will therefore differ for inputs value == 5 ether (it would succeed) while reference would revert.
    function testFuzz_property(uint256 rawAmount, address caller) public {
        // keep caller usable
        vm.assume(caller != address(0));

        // bound amount to a wide range but include typical ether values
        uint256 amount = bound(rawAmount, 0, 20 ether);

        // fund caller so they can send value
        vm.deal(caller, amount);

        // perform call from caller to c.fallback and capture whether it succeeded
        bool ok;
        vm.prank(caller);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C should accept (ok == true) iff amount == 10 ether.
        // This single assert encodes the universal property the reference satisfies and the mutant violates for some inputs (e.g., amount == 5 ether).
        assertTrue( (amount == 10 ether) == ok );
    }
}

