pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and an arbitrary timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero and distinct from contract
        vm.assume(caller != address(0) && caller != address(this));
        // bound timestamp to reasonable future range to avoid overflow issues
        ts = bound(ts, 1, type(uint64).max);

        // Ensure caller has funds and set environment
        vm.deal(caller, 20 ether);

        // read previous value
        uint256 prev = c.pastBlockTime();

        // move time to fuzzed timestamp and perform call with exactly 10 ether
        vm.warp(ts);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // After a valid call with exactly 10 ether, the reference contract guarantees
        // that pastBlockTime is strictly greater than its previous value (monotonic increase).
        // This single assertion must hold for the reference and will fail for the mutant
        // when it allows overwriting with a non-increasing timestamp.
        assertTrue(c.pastBlockTime() > prev);
    }
}

