pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address (as actor) and two timestamps to drive block time progression
    function testFuzz_property(address actor, uint256 t0, uint256 dt) public {
        // keep actor non-zero and amounts reasonable
        vm.assume(actor != address(0));

        // choose two timestamps: t0 will be the first, t1 = t0 + dt (dt may be zero)
        // bound t0 to plausible block times and dt to a small range but allow zero
        uint256 ts0 = bound(t0, 1, 10**10);
        uint256 delta = bound(dt, 0, 1000);
        uint256 ts1 = ts0 + delta;

        // fund actor so they can send 10 ether
        vm.deal(actor, 20 ether);

        // first call at ts0
        vm.warp(ts0);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // read stored value after first call
        uint256 first = c.pastBlockTime();

        // second call at ts1
        vm.warp(ts1);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // read stored value after second call
        uint256 second = c.pastBlockTime();

        // The universal property: for the reference contract, if the second call's timestamp is
        // not strictly greater than the time that produced `first` (i.e., ts1 <= ts0),
        // the contract must not decrease or keep the same pastBlockTime as a result of the second call.
        // More generally, after any later call with 10 ether the stored pastBlockTime must be >= previous.
        // Assert monotonic non-decrease of pastBlockTime across these two calls.
        assertTrue(second >= first);
    }
}

