pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: warpTime is the time we'll set the block.timestamp to when making the call,
    // priorTime is the previous stored pastBlockTime we'll arrange (by first calling at that time).
    function testFuzz_property(uint256 priorTime, uint256 warpTime, address caller) public {
        // Keep values in reasonable 256-bit timestamp ranges
        vm.assume(warpTime <= type(uint64).max);
        vm.assume(priorTime <= type(uint64).max);

        // Step 1: initialize contract's pastBlockTime to priorTime by making an initial valid call
        // We need to ensure initial call has block.timestamp > stored (initially zero) so it updates.
        // Use an arbitrary caller and fund it.
        uint256 initAmount = 10 ether;
        vm.deal(caller, initAmount);
        vm.warp(priorTime); // set time to priorTime
        vm.prank(caller);
        // initial call: since stored was 0, block.timestamp (priorTime) > 0 so reference will update
        (bool okInit,) = address(c).call{value: initAmount}("");
        require(okInit, "initial call failed");

        // confirm that pastBlockTime equals priorTime+1 now (getter)
        uint256 stored = c.pastBlockTime();
        assertTrue(stored == priorTime + 1);

        // Step 2: make a subsequent call at warpTime with same value 10 ether
        // The reference only updates stored if warpTime > previous stored-1 (i.e., previous block time)
        // So if warpTime <= priorTime, the reference should NOT update pastBlockTime; the mutant would.

        vm.deal(caller, initAmount);
        vm.warp(warpTime);
        vm.prank(caller);
        (bool okSecond,) = address(c).call{value: initAmount}("");
        require(okSecond, "second call failed");

        // Single assertion: after the second call, if warpTime <= priorTime then reference must have left pastBlockTime unchanged (still priorTime+1);
        // otherwise (warpTime > priorTime) reference updates to warpTime+1. This is the general rule the reference enforces and the mutant breaks when warpTime <= priorTime.
        if (warpTime <= priorTime) {
            assertTrue(c.pastBlockTime() == priorTime + 1);
        } else {
            assertTrue(c.pastBlockTime() == warpTime + 1);
        }
    }
}

