pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: a block timestamp and a caller address
    function testFuzz_property(uint256 warpTime, address caller) public {
        // Keep inputs in a wide but admissible domain
        // warpTime should be within realistic timestamp bounds
        vm.assume(warpTime <= type(uint64).max);
        // avoid the zero address as caller for clarity
        vm.assume(caller != address(0));

        // Fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // First call at warpTime: ensure block.timestamp > initial pastBlockTime (which is 0)
        vm.warp(uint64(warpTime));
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Record pastBlockTime after first valid call
        uint256 first = c.pastBlockTime();

        // Now perform a second call with the SAME block timestamp (no time advance)
        // In the reference contract, the second call should revert because block.timestamp is NOT > pastBlockTime-1
        // More precisely: reference requires block.timestamp > previous stored pastBlockTime-1 (originally set to warpTime+1),
        // so with same warp the require fails and the reference will revert; BUT note the test must PASS on reference for ALL admissible inputs.
        // To craft a universal property that holds for all inputs on the reference and is violated by the mutant,
        // we instead assert that after the second call (which may revert on the reference), the stored pastBlockTime is either unchanged (reference) or updated (mutant).

        // We must observe only via public interface. We'll attempt the second call and capture whether it succeeded,
        // then assert a condition that reference always ensures: if the second call succeeded, then pastBlockTime after it equals block.timestamp+1.
        // The mutant can succeed when it shouldn't and update pastBlockTime; this assertion still holds for the reference for all admissible inputs
        // and will be violated by the mutant when it updates pastBlockTime despite not satisfying the time ordering before.

        // Make the second call with same timestamp and same caller
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: if the call succeeded, then c.pastBlockTime() == block.timestamp + 1
        // This is a universal property: reference only allows success when time ordering holds and then sets pastBlockTime = block.timestamp+1;
        // mutant can succeed without time ordering, producing a state change that may still equal block.timestamp+1 but importantly
        // there exist inputs (same timestamp) where mutant succeeds and reference reverts; however the assert below checks the state after success,
        // which the mutant can break by succeeding when the reference would have reverted and produce a different pastBlockTime progression in sequences.
        // Read current block.timestamp via warpTime variable (we haven't changed it between calls)
        if (ok) {
            assertTrue(c.pastBlockTime() == uint256(uint64(warpTime)) + 1);
        } else {
            // If the call reverted, the reference also reverts in the same scenario; still need a true assertion reading c.
            // In that case we assert that pastBlockTime remains equal to the first recorded value.
            assertTrue(c.pastBlockTime() == first);
        }
    }
}

