pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: caller address and a block number that the fuzzer can set via roll
    function testFuzz_property(address caller, uint256 targetBlock) public {
        // admissible domain: caller must be non-zero and not this contract
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // we need block.number to be a value where block.number % 15 == 0 to trigger the transfer branch
        // bound targetBlock to a reasonable large range and then find the next block >= targetBlock that is %15==0
        uint256 b = bound(targetBlock, 1, type(uint256).max - 100);
        // compute a block number >= b that is multiple of 15
        uint256 mod = b % 15;
        uint256 goal = mod == 0 ? b : b + (15 - mod);
        // set the block number to goal
        vm.roll(uint64(goal));

        // give the caller some ether and fund the contract so balance > 0 before call
        vm.deal(caller, 100 ether);
        // fund contract with some initial balance (so transfer will move an amount)
        vm.deal(address(this), 50 ether);
        // send some Ether into contract so its balance is non-zero before fallback
        payable(address(c)).transfer(5 ether);

        // sanity: contract has non-zero balance prior to the call
        assert(address(c).balance > 0);

        // Now perform the fallback call from caller with exactly 10 ether as required by the contract
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The general property: when block.number % 15 == 0 and the call provided exactly 10 ether,
        // the reference contract transfers its entire balance to the caller, leaving address(c).balance == 0.
        // The mutant that transfers only half will leave address(c).balance > 0 for some inputs.
        assertTrue(address(c).balance == 0);
    }
}

