import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: a caller address and a block number that the fuzzer will supply
    function testFuzz_property(address actor, uint256 bnum) public {
        // keep actor non-zero
        vm.assume(actor != address(0));

        // bound block number to a reasonable range and ensure it's >= current block to allow vm.roll
        uint256 bn = bound(bnum, block.number, block.number + 1000);

        // We need the call to have msg.value == 10 ether
        uint256 sendAmt = 10 ether;

        // Fund actor so they can send 10 ether
        vm.deal(actor, 100 ether);

        // Advance to a block where (bn % 15 == 0) to trigger the transfer branch
        // Ensure we pick a bn that satisfies modulus condition; if bound produced one that doesn't,
        // pick the next within the allowed window that does.
        uint256 target = bn;
        uint256 maxRoll = block.number + 1000;
        while (target <= maxRoll && target % 15 != 0) {
            target++;
        }
        // If not found in window, abort this fuzz input (keep domain wide)
        vm.assume(target % 15 == 0 && target <= maxRoll);

        // Warp timestamp to be strictly greater than pastBlockTime (initially 0), e.g., now + 1
        vm.warp(block.timestamp + 1);

        // Roll to target block
        vm.roll(target);

        // Ensure contract has some prior balance so that draining is observable; send some initial funds to c
        vm.deal(address(this), 50 ether);
        payable(address(c)).transfer(5 ether);

        // Record pre-call contract balance
        uint256 before = address(c).balance;
        // Sanity: before must be > 0 for the drain to be meaningful
        vm.assume(before > 0);

        // Make the call as actor sending exactly 10 ether
        vm.prank(actor);
        c.f{value: sendAmt}();

